export function validateFile(
  file: File,
  { fileFormats, size }: { fileFormats?: string[]; size?: number } = {},
) {
  if (!file) {
    return Promise.reject(new Error('Файл не выбран'));
  }

  if (!fileFormats?.includes(file.type.toLocaleLowerCase())) {
    return Promise.reject(
      new Error(`Файл недопустимого типа ${file.type}. Допустимы: (${fileFormats?.join(', ')})`),
    );
  }

  if (size && file.size > size) {
    return Promise.reject(new Error(`Файл недопустимого размера. (Макс.:${size / 1024}кБ)`));
  }
  return Promise.resolve(file);
}

export function validateImage(
  image: HTMLImageElement,
  { maxWidth, maxHeight }: { maxWidth?: number; maxHeight?: number } = {},
) {
  if ((maxWidth && image.width > maxWidth) || (maxHeight && image.height > maxHeight)) {
    return Promise.reject(
      new Error(`Изображение превышает допустимые размеры ${maxWidth}/${maxHeight} px`),
    );
  }

  return Promise.resolve(image);
}
export function getImageNodeFromFile(file: File): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    try {
      const reader = new FileReader();
      const img = new Image();

      reader.readAsDataURL(file);

      reader.onload = function (e) {
        img.src = e.target?.result as string;
        img.onload = () => resolve(img);
        img.onerror = reject;
      };

      reader.onerror = reject;
    } catch (e) {
      reject(e);
    }
  });
}
