import React from 'react';

import ReactCrop, { type Crop } from 'react-image-crop';

import PohButton, { ButtonVariant } from '@ui-kit/Button';

import 'react-image-crop/dist/ReactCrop.css';

import style from './style.module.less';

// eslint-disable-next-line import/order
import { getMaxZIndex } from '@helpers/zIndexHelper';

const defaultsImageOptions = {
  quality: 80,
  mime: 'image/png',
};

export interface IImageOptionsForImageEditor {
  width?: number;
  height?: number;
  ratio?: number;
  quality?: number;
  mime?: string;
}

interface IImageEditorProps {
  image: HTMLImageElement;
  onSave: (base64: string) => void;
  imageOptions?: IImageOptionsForImageEditor;
  title?: React.ReactNode;
  onCancel?: () => void;
}

const ImageEditor: React.FC<IImageEditorProps> = ({
  image,
  onSave,
  onCancel,
  title = 'Редактирование изображения',
  imageOptions = {},
}) => {
  const imgRef = React.useRef<HTMLImageElement>(null);
  const options = {
    ...defaultsImageOptions,
    ...imageOptions,
  };

  React.useEffect(() => {
    window.document.body.style.overflow = 'hidden';

    return () => {
      window.document.body.style.overflow = '';
    };
  }, []);

  const [crop, setCrop] = React.useState<Crop>({
    x: 0,
    y: 0,
    width: options.width ?? options.height ?? 32,
    height: options.height ?? options.width ?? 32,
    unit: 'px',
  });

  const handleSave = () => {
    if (!imgRef.current) return;
    const canvas = document.createElement('canvas');

    const wRate = image.width / imgRef.current.width;
    const hRate = image.height / imgRef.current.height;

    const naturalCropWidth = crop.width * wRate;
    const naturalCropHeight = crop.height * hRate;

    let canvasWidth = naturalCropWidth;
    let canvasHeight = naturalCropHeight;

    // Корректная обработка фиксированных размеров с сохранением пропорций кадра
    if (options.width && options.height) {
      canvasWidth = options.width;
      canvasHeight = options.height;
    } else if (options.width) {
      canvasWidth = options.width;
      canvasHeight = canvasWidth * (naturalCropHeight / naturalCropWidth);
    } else if (options.height) {
      canvasHeight = options.height;
      canvasWidth = canvasHeight * (naturalCropWidth / naturalCropHeight);
    }

    canvas.width = canvasWidth;
    canvas.height = canvasHeight;

    const ctx = canvas.getContext('2d');
    if (ctx) {
      ctx.drawImage(
        image,
        crop.x * wRate,
        crop.y * hRate,
        naturalCropWidth,
        naturalCropHeight,
        0,
        0,
        canvasWidth,
        canvasHeight,
      );
    }

    const base64 = canvas.toDataURL(options.mime, options.quality / 100);
    onSave(base64);
  };

  let aspectRatio = options.ratio;

  if (options.width && options.height && !options.ratio) {
    aspectRatio = options.width / options.height;
  }

  return (
    <div className={style.overlay} style={{ zIndex: getMaxZIndex() }}>
      <header className="p-2 bg-light d-flex justify-content-between align-items-center">
        <h5 className="d-none d-md-block">{title}</h5>
        <div className="text-end">
          <PohButton variant={ButtonVariant.Secondary} className="me-2" onClick={onCancel}>
            Отмена
          </PohButton>
          <PohButton onClick={handleSave}>Сохранить</PohButton>
        </div>
      </header>
      <section>
        <ReactCrop
          crop={crop}
          aspect={aspectRatio}
          onChange={(c) => {
            //console.log(c);
            setCrop(c);
          }}
        >
          <img
            src={image.src}
            className={style.image}
            ref={imgRef}
            onLoad={(e) => {
              const el = e.target as HTMLImageElement;
              if (
                image.naturalWidth > image.naturalHeight &&
                image.naturalWidth > document.documentElement.clientWidth
              ) {
                el.style.width = '98%';
              } else if (
                image.naturalHeight > image.naturalWidth &&
                image.naturalHeight > document.documentElement.clientHeight
              ) {
                el.style.height = '98%';
              }

              const wRate = el.width / image.width;
              const hRate = el.height / image.height;

              setCrop((cur) => {
                return {
                  ...cur,
                  width: cur.width * wRate,
                  height: cur.height * hRate,
                  x: cur.x * wRate,
                  y: cur.y * hRate,
                };
              });
            }}
          />
        </ReactCrop>
      </section>
    </div>
  );
};

export default ImageEditor;
