import React, { ReactNode } from 'react';

import ReactDOM from 'react-dom';
import { createRoot } from 'react-dom/client';

import ImageEditor, { IImageOptionsForImageEditor } from './ImageEditor';

/**
 * IImageOptionsForImageEditor
 * @typedef IImageOptionsForImageEditor
 * @property {number} [width] - target width of image
 * @property {number} [height] - target height of image
 * @property {number} [ratio] - 3/4 or 1 or more
 * @property {number} [quality=100] - 0-100
 * @property {number} [mime=image/png] - mime type of result image
 */

/**
 * Редактор изображения (обрезка)
 * @param {HTMLElement} image - file[0]
 * @param {IImageOptionsForImageEditor} [options]
 * @param {string} [title]
 * @returns {Promise<string>} base64 image
 */
export const editImageAsync = (
  image: HTMLImageElement,
  options: IImageOptionsForImageEditor,
  title?: ReactNode,
): Promise<string> =>
  new Promise((resolve, reject) => {
    const node = document.createElement('div');
    document.body.appendChild(node);

    const clear = () => {
      const root = createRoot(node);
      root.unmount();
      node.parentNode?.removeChild(node);
    };

    const handleCancel = () => {
      clear();
      reject();
    };
    const handleSave = (base64: string) => {
      clear();
      resolve(base64);
    };
    const root = createRoot(node);

    root.render(
      <ImageEditor
        image={image}
        imageOptions={options}
        title={title}
        onSave={handleSave}
        onCancel={handleCancel}
      />,
    );
  });

export default ImageEditor;
